CREATE DATABASE CUSTOMER;
USE CUSTOMER;
select * FROM DATA limit 10;

-- what is the total revenue generated by male and female ?

select gender ,sum(purchase_amount) as revenue 
from data 
group by gender;

-- ehich customer used a discount but still spend above a average purchase


select customer_id,purchase_amount
from data
where discount_applied="yes" and purchase_amount<=(select avg(purchase_amount) from data); 


-- what are the top 5 highest product with the highest avg review rate 


select item_purchased , avg(review_rating) as average
from data 
group by item_purchased
order by avg(item_purchased) desc
limit 5;



-- compare the average between the standard and express shipping

select shipping_type ,avg(purchase_amount)  as average_revenue from data
where shipping_type in("standard","express")
group by shipping_type;


-- CALCULATE THE AVERAGE SPEND BETWEEN SUBSRIBER AND NOT SUBSCRIBER 

SELECT subscription_status ,avg(purchase_amount) as average_revenue,
sum(purchase_amount) as total_revenue
from data
where subscription_status in ("yes","no")
group by subscription_status;



-- which 5 product have higest percentage of  sales with discount applied
select item_purchased , 100*sum(case when discount_applied="yes" then 1 else 0 end )/count(*) as discount_rate
from data
group by item_purchased
order by discount_rate
limit 5;


-- segment the customer with therer previous purchased sales 

with cte as (
select customer_id ,previous_purchases ,
 case
 when previous_purchases = 1 then "new"
 when previous_purchases between 2 and 10 then "returning"
 else "loyal" 
 end  as customer_segment 
 from data)
  select customer_segment ,count(*) as 'number of customere'
  from cte
  group by customer_segment ;
 
 -- top 3 product with each category
 
with cte as(
select category,count(customer_id)as total_orders ,item_purchased ,
row_number() over(partition by category order by count(customer_id) desc ) as rnk
from data  
group by category,item_purchased
)  
select item_purchased , category , total_orders from cte
where rnk <=3;



-- the repeat buyers have subcription

select subscription_status,count(customer_id) as repeat_customer
from data
where previous_purchases >5
group by subscription_status;


select age_grouped,sum(purchase_amount) as total_revenue
from data 
group by age_grouped
order by total_revenue desc


